def get_operation():
    """Get user input for the operation to perform."""
    while True:
        operation = input("Enter the operation (+, -, *, /): ").strip()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("Invalid input. Please enter a valid operation (+, -, *, /).")

def get_numbers():
    """Get user input for the two numbers to perform the operation on."""
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            return num1, num2
        except ValueError:
            print("Invalid input. Please enter numbers.")

def perform_operation(num1, num2, operation):
    """Perform the specified operation on the two numbers."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
        result = num1 - num2
    elif operation == '*':
        result = num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        result = num1 / num2
    else:
        raise ValueError("Invalid operation. Please enter a valid operation (+, -, *, /).")
    return result

if __name__ == "__main__":
    operation = get_operation()
    num1, num2 = get_numbers()
    try:
        result = perform_operation(num1, num2, operation)
        print(f"{num1} {operation} {num2} = {result}")
    except ValueError as e:
        print(e)
```
